-- bio_plus shots — A5 «Точка невозврата» (25 shots, October 2022, Mogilev)
BEGIN;

INSERT INTO shots (id, "projectId", "sceneId", "shotCode", "promptFields", "shotType", "cameraAngle", "cameraMove", "storyBeat", "narrativeFunction", "vignetteSlug", "isBroll", "isIconic", "timeOfDay", "paletteKey", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, p.id, s.id, v.shot_code, v.prompt_fields::jsonb, v.shot_type, v.camera_angle, v.camera_move, v.story_beat, v.narrative_function, v.vignette_slug, v.is_broll, v.is_iconic, v.time_of_day, v.palette_key, NOW(), NOW()
FROM projects p
JOIN scenes s ON s."projectId" = p.id AND s."sceneKey" = 'act_05_no_return'
CROSS JOIN (VALUES
  ('A5_SH01', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, wide shot of interior of Cafe Lido in Mogilev on Pervomayskaya street October 2022 afternoon, sparse tables with worn vinyl banquettes faded floral curtains small wooden counter at far end, {HEROINE_ELENA_AGE_42} seated at window table on far side facing camera, in foreground at near side of table only back of FRIEND_LARISA dark-brown low ponytail and grey cardigan shoulder visible — face NOT in frame, between them cup of tea (heroine side) and cup of cappuccino (Larisa side), cool grey overcast daylight from window on right, hard ink outline on heroine table cafe interior cell-shaded color blocks muted cafe tones cool window light, WS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Октябрь две тысячи двадцать второго, кафе Лидо на Первомайской, три часа дня, ты заказала чай"}$pp$, 'WS', 'eye', 'static', 'bad_guys_close_in', 'atmosphere', 'heroine_elena', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH02', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, medium shot of {FRIEND_LARISA_AGE_42} seated at cafe table facing slightly toward camera, thin oval brushed-silver glasses grey wool cardigan over black turtleneck hair pulled back in low ponytail, hands open and resting on tabletop palms up, at right foreground edge only heroine left shoulder visible (no face), cool grey overcast from window from right dim warm bulb above, hard ink outline on Larisa face glasses hands cell-shaded skin two-tone glasses catch cool window light, MS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Напротив тебя сидит Лариса, это вы вдвоём впервые за восемь месяцев, она сама позвонила"}$pp$, 'MS', 'eye', 'static', 'bad_guys_close_in', 'character', 'friend_larisa', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH03', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, close-up of {FRIEND_LARISA_AGE_42} face and upper body across cafe table, both palms open on worn wooden tabletop fingers spread no jewelry, her face neutral lips pale glasses catching cool window light, expression of someone delivering bad news without aggression, cool window light from frame-right dim ambient from above, hard ink outline on face glasses palms tabletop grain cell-shaded skin two-tone with subtle hatching at brow, CU eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Очки в металлической оправе, чёрная водолазка, серьёзное лицо без улыбки, она положила руки на стол"}$pp$, 'CU', 'eye', 'static', 'bad_guys_close_in', 'character', 'friend_larisa', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH04', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, close-up of {FRIEND_LARISA_AGE_42} three-quarter view mid-sentence, mouth open with calm steady cadence (not shouting) eyes locked steady, cool window light from right dim bulb overhead glasses frames catching cool light, hard ink outline on face hair glasses mouth contour cell-shaded skin two-tone with subtle hatching at temple, CU eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Она говорит, я вышла из структуры в августе, и прошу тебя один раз, остановись и посмотри"}$pp$, 'CU', 'eye', 'static', 'bad_guys_close_in', 'character', 'friend_larisa', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH05', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, close-up of {HEROINE_ELENA_AGE_42} three-quarter view eyes narrowed in dry controlled anger, mouth set in thin line jaw tight faint colour rising in cheeks, silver chain visible at open blouse collar (cross hidden) small mole on left jawline visible, cool window light from right warm dim bulb from above, hard ink outline on face jaw line mole hair strands cell-shaded skin two-tone with subtle hatching at tightened jaw, CU eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты говоришь, ты просто не выдержала, не у всех получается, у меня получается"}$pp$, 'CU', 'eye', 'static', 'bad_guys_close_in', 'character', 'heroine_elena', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH06', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, over-the-shoulder shot from behind heroine looking past her left shoulder at {FRIEND_LARISA_AGE_42}, Larisa extending smartphone across table toward heroine screen facing camera/heroine, on phone screen visible cyrillic text МФО ДОЛГ — 14 000 BYN — 24 МЕС with red overdue marker beside amount, cool window light from frame-right dim warm bulb from above, hard ink outline on Larisa face phone screen cyrillic figures cell-shaded color warm phone screen catch cool ambient heroine shoulder in soft shadow, OTS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Лариса протягивает тебе телефон, на экране её собственный долг МФО за два года, четырнадцать тысяч"}$pp$, 'OTS', 'eye', 'static', 'bad_guys_close_in', 'plot', 'friend_larisa', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH07', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, close-up of {HEROINE_ELENA_AGE_42} turning head away from camera-left toward cafe window on right, profile view her gaze on single droplet of last rain sliding down outside of glass, cool flat window-light flooding side of face nearest glass warm dim bulb from behind warming back of head and hair edges, hard ink outline on profile hair window frame droplet cell-shaded skin two-tone with subtle hatching at cheek shadow, CU eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты отворачиваешься, ты говоришь, это твой долг, я живу свою жизнь, спасибо за беспокойство"}$pp$, 'CU', 'eye', 'static', 'bad_guys_close_in', 'character', 'heroine_elena', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH08', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, wide shot of {HEROINE_ELENA_AGE_42} walking along wet pavement of Pervomayskaya street under light October rain, brown autumn knee-length coat hood NOT raised hair slowly getting wet at temples, cool grey overcast sky wet asphalt reflecting grey above, few yellow leaves stuck to pavement no other pedestrians, hard ink outline on silhouette rain streaks barely visible as thin vertical lines cell-shaded color brown coat grey wet pavement cool overcast sky, WS eye level tracking laterally 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты выходишь из кафе под дождь, капюшон не накидываешь, хочешь, чтобы холодная вода била тебя по голове"}$pp$, 'WS', 'eye', 'track_lateral', 'bad_guys_close_in', 'character', 'heroine_elena', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH09', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, close-up of {HEROINE_ELENA_AGE_42} walking lips silently moving repeating single phrase three times, rain on cheek and brow hair sodden at temples sticking to face, eyes focused on pavement ahead not blinking despite rain, flat cool overcast light from above no warmth, hard ink outline on face wet hair strands raindrops on cheekbone cell-shaded skin in cool monotone, CU eye level walking-along match 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты идёшь и говоришь себе, она просто завидует, она просто завидует, она просто завидует"}$pp$, 'CU', 'eye', 'static', 'bad_guys_close_in', 'character', 'heroine_elena', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH10', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, back shot of {HEROINE_ELENA_AGE_42} pushing open heavy metal entrance door of her panel-building stairwell, behind her grey rain-soaked courtyard empty playground swing-set sodden, inside stairwell warm yellow neon bulb starting to spill onto her wet hair, hard ink outline on back silhouette door swing-set behind cell-shaded color cool rain-grey behind warm yellow neon ahead — palette transition, BACK eye level tracking laterally 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты заходишь в свой подъезд, на лестничной клетке пахнет жареной картошкой из двадцать четвёртой"}$pp$, 'BACK', 'eye', 'track_lateral', 'bad_guys_close_in', 'transition', 'heroine_elena', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH11', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, wide shot of Mogilev apartment kitchen at half past one in morning, single deep-amber pendant lamp hanging low over round wooden kitchen table casting circular pool of warm light, on table calculator stack of paper bills with red overdue stamps the BIO+ Bystrokredit loan contract, on floor against every wall nine turquoise BIO+ cardboard boxes of various sizes, kitchen window above sink completely black (deep night), everything outside lamp pool of light in deep blue-black shadow, heroine NOT in frame for this shot — pure environment, hard ink outline on boxes lamp table elements paper edges cell-shaded color blocks warm amber pool turquoise boxes muted deep blue-black shadow, WS eye level locked off 16:9 iconic", "negativeRef": "{NEG}", "narrationRu": "Полвторого ночи, на кухне одна жёлтая лампа, девять бирюзовых коробок и распечатки долговых ведомостей"}$pp$, 'WS', 'eye', 'static', 'bad_guys_close_in', 'iconic', NULL, TRUE, TRUE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH12', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, extreme close-up pushing in slowly on stack of printed loan paperwork on kitchen table under amber pendant lamp, top sheet Bystrokredit loan statement with cyrillic text and thick red rubber-stamped marker reading ПРОСРОЧКА 28 СЕНТЯБРЯ — 1 200 BYN over lower right corner, beneath that Belarusbank credit-card statement with smaller debt figures, warm amber pendant catchlight on paper deep shadow at edges, hard ink outline on every cyrillic letterform and red stamp impression cell-shaded color pale paper red stamp ink-black text warm amber wash, ECU eye level slow push-in 16:9", "negativeRef": "{NEG}", "narrationRu": "На столе договор БыстроКредита и лист с отметкой просрочки, двадцать восьмое сентября, тысяча двести"}$pp$, 'ECU', 'eye', 'push_in', 'bad_guys_close_in', 'plot', NULL, TRUE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
