  ('A5_SH16', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, close-up of smartphone screen showing video call to {SPONSOR_SVETA_AGE_46_ROBE}, Sveta visible from shoulders up in her bedroom in beige terrycloth robe NO makeup dark circles under eyes hair flat and loose no badge on robe, behind her dim blue ambient light from bedside nightlight soft pillow visible behind shoulder, phone-screen edge visible at frame edges (we see her THROUGH the screen), hard ink outline on face robe collar screen frame cell-shaded skin two-tone with faint blue cast (bedroom nightlight tint), CU eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Светлана в халате, без помады, под глазами тени, она не спрашивает, что случилось, она ждёт"}$pp$, 'CU', 'eye', 'static', 'bad_guys_close_in', 'character', 'sponsor_sveta', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH17', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, over-the-shoulder shot from behind heroine left shoulder in dim kitchen, in foreground only back of heroine head ash-brown hair and dark cardigan shoulder visible — face NOT in frame, beyond her in sharp focus smartphone held in her hand showing {SPONSOR_SVETA_AGE_46_ROBE} on video-call screen, on kitchen table soft-focus debt papers and calculator, warm amber pendant lamp glow on heroine hair from above cool phone-screen glow on right side of face (we see only rim of cheek), hard ink outline on heroine back silhouette and phone screen frame cell-shaded color two-tone, OTS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты говоришь, я не вытяну этот квартал, просрочки растут, у меня нет двух тысяч на закупку"}$pp$, 'OTS', 'eye', 'static', 'bad_guys_close_in', 'character', 'heroine_elena', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
