  ('A5_SH20', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, extreme close-up of smartphone screen showing {SPONSOR_SVETA_AGE_46_ROBE} now closer to her phone camera in three-quarter view holding single sheet of paper up beside her face, on paper large bold cyrillic number 18 000 and beneath БРИЛЛИАНТОВЫЙ СТАРТ, warm amber bedside lamp now visible behind her shoulder (she has turned on second light), hard ink outline on face paper cyrillic numerals cell-shaded color warm bedside lamp now competing with cool nightlight paper bright, ECU on screen surface eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Она говорит, восемнадцать тысяч стартовый Брильянтовый пакет, четыре месяца до отбоя, Минск, БМВ"}$pp$, 'ECU', 'eye', 'static', 'bad_guys_close_in', 'plot', 'sponsor_sveta', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH21', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, close-up pushing in slowly on {HEROINE_ELENA_AGE_42} three-quarter view in dim kitchen, slight return of warm internal glow on cheekbone — BUT warm tone is muddied with cool steel-grey overlay (metallic-tinted leitmotif return), eyes slightly more focused than SH19 mouth set firm, warm amber pendant overhead cool phone-screen glow from right, hard ink outline on face muted cheekbone glow rendered with thin steel-tone hatching layered over warm cell-shaded skin two-tone with third layered metallic tone on cheekbone, CU eye level slow push-in 16:9", "negativeRef": "{NEG}", "narrationRu": "Узел в груди медленно возвращается, у него появился металлический привкус, как от батарейки"}$pp$, 'CU', 'eye', 'push_in', 'bad_guys_close_in', 'character', 'heroine_elena', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH22', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, close-up of smartphone screen showing {SPONSOR_SVETA_AGE_46_ROBE} pressing right palm flat against her phone screen on her end of call, palm filling upper half of heroine screen view fingers slightly splayed, behind palm her face partially visible eyes intent makeup absent, gesture intimate almost cult-like, warm amber and cool blue mixed light on her side, hard ink outline on palm fingers face fragment screen frame cell-shaded color two-tone, CU on screen surface eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Светлана говорит, я с тобой, я лично поеду с тобой к нотариусу, я знаю одного на Ленинской"}$pp$, 'CU', 'eye', 'static', 'bad_guys_close_in', 'character', 'sponsor_sveta', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH23', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, close-up of {HEROINE_ELENA_AGE_42} three-quarter view slow controlled nod, phone screen glow from her right falling as sharp blue rectangle of light across face, warm amber pendant from above continues, eyes downcast lips set thin in acceptance, hard ink outline on face hair geometric blue rectangle of screen-light cell-shaded skin two-tone with cool screen-rectangle laid sharply over warm-amber base, CU eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Ты медленно киваешь в трубку, она тебя не видит, но она знает, что ты киваешь"}$pp$, 'CU', 'eye', 'static', 'bad_guys_close_in', 'character', 'heroine_elena', FALSE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH24', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, close-up of smartphone screen on dark kitchen table showing incoming chat message, sender name СВЕТЛАНА ОРЛОВА at top message in cyrillic blue chat bubble завтра в 10 Болдина 12 такси за тобой в 9:40 ✓, beside message small green checkmark indicating delivered, warm amber pendant lamp from above casting glow on dark table around phone, hard ink outline on every cyrillic letterform screen frame message bubble cell-shaded color dark phone bright screen ink-black text on white bubble, CU on screen eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Она говорит, утром в десять у меня в офисе на Болдина двенадцать, я закажу за тобой такси"}$pp$, 'CU', 'eye', 'static', 'bad_guys_close_in', 'plot', NULL, TRUE, FALSE, 'october_night_2022', 'A5_grey_amber_night'),
  ('A5_SH25', $pp${"positivePrompt": "{STYLE}, {PALETTE_A5}, close-up pushing in slowly on {HEROINE_ELENA_AGE_42} placing smartphone face-down on table in front of her, beyond her shoulder kitchen window utterly black (deepest night), gaze fixes on black window glass no expression movement, warm-cheek glow is back BUT with steel-grey metallic hatching layered fully — leitmotif now fully mutated, warm amber pendant overhead no phone-screen blue anymore (phone face-down), hard ink outline on profile hair phone edge window frame metallic-grey contamination on cheekbone cell-shaded skin three-tone warm base + cool fill + steel overlay on cheek, CU eye level slow push-in 16:9 iconic mutation composition", "negativeRef": "{NEG}", "narrationRu": "Ты кладёшь телефон экраном вниз, окно чёрное, узел тяжёлый, металлический, и при этом ещё тёплый"}$pp$, 'CU', 'eye', 'push_in', 'bad_guys_close_in', 'iconic', 'heroine_elena', FALSE, TRUE, 'october_night_2022', 'A5_grey_amber_night')
